"use client";

import { authClient } from "@/lib/auth-client";
import { useState, useCallback, useRef, useEffect, Suspense } from "react";
import Link from "next/link";
import Image from "next/image";
import Script from "next/script";
import { Button } from "@/components/ui/button";
import { useRouter, useSearchParams } from "next/navigation";
import { DEFAULT_MODEL } from "@/lib/constants";
import { getSafeCallbackUrl } from "@/lib/safe-redirect";
import { savePendingProject } from "@/lib/pending-project";
import { CometSpinner } from "@/components/loading-ui/comet-spinner";

function SignUpForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [captchaToken, setCaptchaToken] = useState("");
  const captchaContainerRef = useRef<HTMLDivElement>(null);
  const captchaWidgetIdRef = useRef<string | null>(null);
  const router = useRouter();
  const searchParams = useSearchParams();
  const callbackUrlRef = useRef(
    getSafeCallbackUrl(searchParams.get("callbackUrl"), "/"),
  );
  const turnstileSiteKey = process.env.NEXT_PUBLIC_TURNSTILE_SITE_KEY;

  useEffect(() => {
    const query = searchParams.get("query")?.trim();
    if (!query) return;

    savePendingProject({
      prompt: query,
      model: DEFAULT_MODEL,
      quality: "low",
    });
  }, [searchParams]);

  const renderTurnstile = useCallback(() => {
    if (
      !turnstileSiteKey ||
      !captchaContainerRef.current ||
      !window.turnstile ||
      captchaWidgetIdRef.current
    ) {
      return;
    }

    captchaWidgetIdRef.current = window.turnstile.render(
      captchaContainerRef.current,
      {
        sitekey: turnstileSiteKey,
        theme: "auto",
        callback: setCaptchaToken,
        "expired-callback": () => setCaptchaToken(""),
        "error-callback": () => setCaptchaToken(""),
      },
    );
  }, [turnstileSiteKey]);

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const { error: signUpError } = await authClient.signUp.email(
        {
          email,
          password,
          name,
          callbackURL: callbackUrlRef.current,
        },
        captchaToken
          ? { headers: { "x-captcha-response": captchaToken } }
          : undefined,
      );

      if (signUpError) {
        setError(signUpError.message || "Sign up failed");
        return;
      }

      const verifyEmailUrl = new URL("/verify-email", window.location.origin);
      verifyEmailUrl.searchParams.set("email", email);
      verifyEmailUrl.searchParams.set("callbackUrl", callbackUrlRef.current);
      router.push(
        `${verifyEmailUrl.pathname}${verifyEmailUrl.search}${verifyEmailUrl.hash}`,
      );
      router.refresh();
    } catch (err) {
      console.error("Sign up error:", err);
      setError("An error occurred. Please try again.");
    } finally {
      if (captchaWidgetIdRef.current && window.turnstile) {
        window.turnstile.reset(captchaWidgetIdRef.current);
        setCaptchaToken("");
      }
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setLoading(true);
    try {
      await authClient.signIn.social({
        provider: "google",
        callbackURL: callbackUrlRef.current,
      });
    } catch (err) {
      console.error("Google sign in error:", err);
      setError("Google sign in failed. Please try again.");
      setLoading(false);
    }
  };

  const signInHref = `/sign-in?callbackUrl=${encodeURIComponent(callbackUrlRef.current)}`;

  return (
    <div className="flex min-h-screen items-center justify-center">
      {turnstileSiteKey && (
        <Script
          src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit"
          strategy="afterInteractive"
          onReady={renderTurnstile}
        />
      )}
      <div className="w-full max-w-md space-y-8 p-8">
        <div className="text-center">
          <Link
            href="/"
            className="mb-8 inline-flex items-center justify-center transition-transform hover:scale-105"
          >
            <Image
              src="/squidagent-logo.svg"
              alt="Squid Agent"
              width={64}
              height={64}
              loading="eager"
              className="h-16 w-auto"
            />
          </Link>
          <h1 className="text-3xl font-bold tracking-tight">
            Create an account
          </h1>
          <p className="mt-2 text-sm text-muted-foreground">
            Or{" "}
            <Link
              href={signInHref}
              className="font-medium text-primary hover:underline"
            >
              sign in to your existing account
            </Link>
          </p>
        </div>

        <form onSubmit={handleSignUp} className="mt-8 space-y-6">
          {error && (
            <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label htmlFor="name" className="block text-sm font-medium">
                Name
              </label>
              <input
                id="name"
                name="name"
                type="text"
                autoComplete="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                placeholder="Your name"
              />
            </div>

            <div>
              <label htmlFor="email" className="block text-sm font-medium">
                Email address
              </label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                placeholder="you@example.com"
              />
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-medium">
                Password
              </label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="new-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                placeholder="••••••••"
              />
            </div>
          </div>

          {turnstileSiteKey && (
            <div
              ref={captchaContainerRef}
              className="flex min-h-[65px] justify-center"
              aria-label="Bot verification"
            />
          )}

          <Button
            type="submit"
            disabled={loading || Boolean(turnstileSiteKey && !captchaToken)}
            className="w-full"
          >
            {loading ? (
              <>
                <CometSpinner className="size-4" aria-hidden="true" />
                Creating account...
              </>
            ) : (
              "Sign up"
            )}
          </Button>

          <div className="relative">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-border" />
            </div>
            <div className="relative flex justify-center text-sm">
              <span className="bg-background px-2 text-muted-foreground">
                Or continue with
              </span>
            </div>
          </div>

          <Button
            type="button"
            onClick={handleGoogleSignIn}
            disabled={loading}
            variant="outline"
            className="min-h-[48px] w-full"
          >
            {loading ? (
              <CometSpinner className="size-4" aria-hidden="true" />
            ) : (
              <svg className="h-5 w-5" viewBox="0 0 24 24">
                <path
                  fill="currentColor"
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                />
                <path
                  fill="currentColor"
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                />
                <path
                  fill="currentColor"
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                />
                <path
                  fill="currentColor"
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                />
              </svg>
            )}
            {loading ? "Connecting..." : "Google"}
          </Button>
        </form>
      </div>
    </div>
  );
}

export default function SignUpPage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen items-center justify-center">
          <CometSpinner
            className="size-8 text-primary"
            aria-label="Loading sign up"
            variant="page"
          />
        </div>
      }
    >
      <SignUpForm />
    </Suspense>
  );
}
